script:
if (-not $ACCOUNT) { throw 'ACCOUNT is required' }
$type = if ($ACCOUNT_TYPE) { $ACCOUNT_TYPE } else { 'computer' }
$mode = if ($MODE) { $MODE } else { 'unconstrained' }
$set = ($mode -eq 'unconstrained')
if ($type -eq 'computer') {
    $acct = "$ACCOUNT`$"
    $existing = Get-ADComputer -Filter "SamAccountName -eq '$acct'" -ErrorAction Ignore
    if (-not $existing) { New-ADComputer -Name $ACCOUNT -Enabled $true | Out-Null }
} else {
    $existing = Get-ADUser -Filter "SamAccountName -eq '$ACCOUNT'" -ErrorAction Ignore
    if (-not $existing) { throw "AD user '$ACCOUNT' does not exist (pair with ad-user-win)" }
}
Set-ADAccountControl -Identity $ACCOUNT -TrustedForDelegation $set -TrustedToAuthForDelegation $set
